head.script:
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
scwin.fr_SecuGrpId = SECUGRP_ID_EW; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);

        // img_Elwlist.ActiveIndex = 1 ;
        await scwin.search2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Search2_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search2_onclick = async function() {
    try {
        await scwin.search2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.img_Search2_onclick" });
    }
};

/**
 * @method
 * @name dts2_OnLoadError
 * @description dts2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.dts2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts2_OnLoadCompleted
 * @description dts2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts2_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt2.setValue("총 " + rowcount + " 건");
        // dts2.RowPosition = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05920.dts2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close2_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Close2_onclick = function() {
    try {
        window.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05920.img_Close2_onclick" });
    }
};

/**
 * @method
 * @name img_Regist2_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist2_onclick = async function() {
    try {
        scwin.fn_GetPar = scwin.getParNew2;
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.img_Regist2_onclick" });
    }
};

/**
 * @method
 * @name img_Excel2_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel2_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF05920.xml", SCREN_PROCS_TP_CD_07);
        if (dts2.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd2, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "행사종료일(D-30) 상장폐지 예고내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.img_Excel2_onclick" });
    }
};

/**
 * @method
 * @name grd2_OnDblClick
 * @description grd2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd2_OnDblClick = async function(row, colid) {
    try {
        scwin.fn_GetPar = scwin.getParUpdate2; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05920.grd2_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search2
 * @description search2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search2 = async function() {
    url += "&SCREN_ID=" + "ULDSTF05920.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts2",
        action : "/Delisting.do",
        ref : "",
        target : "dts2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParUpdate2
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[1] = scwin.fr_MktId; // 시장구분
    arrPar[2] = dts2.getCellData(dts2.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[3] = dts2.getCellData(dts2.getRowPosition(), "WRT_DD"); // 최종거래일

    return arrPar.length;
};

/**
 * @method
 * @name getParNew2
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew2 = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[1] = scwin.fr_MktId; // 시장구분
    arrPar[2] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[3] = $c.ut.cGetToday("yyyymmdd");
};

/**
 * @method
 * @name newpreCreateFrame2
 * @description newpre Create Frame2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame2 = async function() {
    const options = {
        id: "ULDSTF05922",
        title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 행사종료일 1개월전(D-1MONTH) 상장폐지 예고",
        type: "browserPopup",
        width: "680px",
        height: "570px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../lstproc/ULDSTF05922.gfm", options);
    await scwin.search2(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
